package bus

import chisel3._
import chisel3.util._
import coralnpu.Parameters

/**
  * DMA Engine with TileLink-UL host (master) and device (CSR slave) ports.
  *
  * CSR Map (device port, 32-bit registers):
  *   0x00 : CTRL      (r/w)  - bit 0: enable, bit 1: start, bit 2: abort
  *   0x04 : STATUS    (r/o)  - bit 0: busy, bit 1: done, bit 2: error
  *   0x08 : DESC_ADDR (r/w)  - descriptor physical address
  *
  * Descriptor format (32 bytes at DESC_ADDR):
  *   +0x00 : src_addr  (32-bit)
  *   +0x04 : dst_addr  (32-bit)
  *   +0x08 : flags     - bits[23:0]: xfer_len, bits[26:24]: xfer_width (log2 bytes/beat),
  *                       bit[27]: src_fixed, bit[28]: dst_fixed, bit[29]: poll_en
  *   +0x0c : next_desc (32-bit, 0 = no chaining)
  *   +0x10 : poll_addr
  *   +0x14 : poll_mask
  *   +0x18 : poll_value
  *   +0x1c : reserved
  */
class DmaEngine(hostP: Parameters, deviceP: Parameters) extends Module {
  val hostTlp   = new TLULParameters(hostP)
  val deviceTlp = new TLULParameters(deviceP)

  val io = IO(new Bundle {
    val tl_host   = new OpenTitanTileLink.Host2Device(hostTlp)       // master
    val tl_device = Flipped(new OpenTitanTileLink.Host2Device(deviceTlp)) // slave
  })

  // =========================================================================
  // CSR Registers
  // =========================================================================
  val ctrlReg     = RegInit(0.U(32.W))
  val statusReg   = RegInit(0.U(32.W))
  val descAddrReg = RegInit(0.U(32.W))

  val ctrlEnable = ctrlReg(0)
  val ctrlStart  = ctrlReg(1)
  val ctrlAbort  = ctrlReg(2)

  val statusBusy  = statusReg(0)
  val statusDone  = statusReg(1)
  val statusError = statusReg(2)

  // =========================================================================
  // Device port TL-UL slave (CSR access)
  // =========================================================================
  val sDevIdle :: sDevResp :: Nil = Enum(2)
  val devState = RegInit(sDevIdle)

  val devRespData   = RegInit(0.U(deviceTlp.dataBits.W))
  val devRespError  = RegInit(false.B)
  val devRespSource = RegInit(0.U(deviceTlp.sourceBits.W))
  val devRespSize   = RegInit(0.U(deviceTlp.sizeBits.W))
  val devRespOpcode = RegInit(TLULOpcodesD.AccessAck)

  io.tl_device.a.ready := false.B
  io.tl_device.d.valid := false.B
  io.tl_device.d.bits  := 0.U.asTypeOf(new TLULChannelD(deviceTlp))

  // Wires for CSR writes from device port
  val csrWriteEn       = WireDefault(false.B)
  val csrWriteAddr     = WireDefault(0.U(32.W))
  val csrWriteData     = WireDefault(0.U(32.W))

  switch(devState) {
    is(sDevIdle) {
      io.tl_device.a.ready := true.B
      when(io.tl_device.a.valid) {
        val addr    = io.tl_device.a.bits.address
        val isWrite = (io.tl_device.a.bits.opcode === TLULOpcodesA.PutFullData) ||
                      (io.tl_device.a.bits.opcode === TLULOpcodesA.PutPartialData)
        val isGet   = io.tl_device.a.bits.opcode === TLULOpcodesA.Get

        devRespSource := io.tl_device.a.bits.source
        devRespSize   := io.tl_device.a.bits.size
        devRespError  := false.B
        devRespData   := 0.U

        when(isGet) {
          devRespOpcode := TLULOpcodesD.AccessAckData
          when(addr === 0x00.U) {
            devRespData := ctrlReg
          }.elsewhen(addr === 0x04.U) {
            devRespData := statusReg
          }.elsewhen(addr === 0x08.U) {
            devRespData := descAddrReg
          }.otherwise {
            devRespData  := 0.U
            devRespError := true.B
          }
        }.elsewhen(isWrite) {
          devRespOpcode := TLULOpcodesD.AccessAck
          // STATUS (0x04) is read-only
          when(addr === 0x04.U) {
            devRespError := true.B
          }.elsewhen(addr === 0x00.U || addr === 0x08.U) {
            csrWriteEn   := true.B
            csrWriteAddr := addr
            csrWriteData := io.tl_device.a.bits.data(31, 0)
          }.otherwise {
            devRespError := true.B
          }
        }.otherwise {
          devRespOpcode := TLULOpcodesD.AccessAck
          devRespError  := true.B
        }

        devState := sDevResp
      }
    }

    is(sDevResp) {
      io.tl_device.d.valid        := true.B
      io.tl_device.d.bits.opcode  := devRespOpcode
      io.tl_device.d.bits.param   := 0.U
      io.tl_device.d.bits.size    := devRespSize
      io.tl_device.d.bits.source  := devRespSource
      io.tl_device.d.bits.sink    := 0.U
      io.tl_device.d.bits.denied  := false.B
      io.tl_device.d.bits.data    := devRespData
      io.tl_device.d.bits.corrupt := false.B
      io.tl_device.d.bits.error   := devRespError

      when(io.tl_device.d.ready) {
        devState := sDevIdle
      }
    }
  }

  // CSR register updates (from device port)
  when(csrWriteEn) {
    when(csrWriteAddr === 0x00.U) {
      ctrlReg := csrWriteData
    }.elsewhen(csrWriteAddr === 0x08.U) {
      descAddrReg := csrWriteData
    }
  }

  // =========================================================================
  // DMA FSM (host port master)
  // =========================================================================
  // States
  val dIdle :: dLoadDesc :: dWaitDesc :: dXferRead :: dWaitRead :: dXferWrite :: dWaitWrite :: dDone :: dError :: Nil = Enum(9)
  val dmaState = RegInit(dIdle)

  // Descriptor fields
  val descSrcAddr  = RegInit(0.U(32.W))
  val descDstAddr  = RegInit(0.U(32.W))
  val descXferLen  = RegInit(0.U(24.W))  // bytes
  val descXferWidth = RegInit(0.U(3.W)) // log2 bytes per beat
  val descSrcFixed = RegInit(false.B)
  val descDstFixed = RegInit(false.B)
  val descPollEn   = RegInit(false.B)
  val descNextDesc = RegInit(0.U(32.W))
  val descPollAddr = RegInit(0.U(32.W))
  val descPollMask = RegInit(0.U(32.W))
  val descPollValue = RegInit(0.U(32.W))

  // Transfer progress
  val xferSrcAddr  = RegInit(0.U(32.W))
  val xferDstAddr  = RegInit(0.U(32.W))
  val xferRemain   = RegInit(0.U(32.W))  // bytes remaining
  val xferBeatSize = RegInit(0.U(32.W))  // bytes per beat

  // Descriptor loading: 8 words of 4 bytes each (0x00..0x1c)
  val descLoadIdx  = RegInit(0.U(4.W))    // 0..7
  val descWords    = Reg(Vec(8, UInt(32.W)))

  // In-flight read data (for write phase)
  val readDataReg = RegInit(0.U(hostTlp.dataBits.W))

  // Default host port outputs
  io.tl_host.a.valid      := false.B
  io.tl_host.a.bits       := 0.U.asTypeOf(new TLULChannelA(hostTlp))
  io.tl_host.d.ready      := false.B

  // Beat size calculation
  val beatBytes = WireDefault(4.U(32.W))  // default 4 bytes

  // Status register update logic
  val statusBusyNext  = WireDefault(statusBusy)
  val statusDoneNext  = WireDefault(statusDone)
  val statusErrorNext = WireDefault(statusError)

  // -------------------------------------------------------------------------
  // DMA FSM transitions
  // -------------------------------------------------------------------------
  switch(dmaState) {
    is(dIdle) {
      // Start when enable=1 and start=1
      when(ctrlEnable && ctrlStart && !statusBusy) {
        statusBusyNext  := true.B
        statusDoneNext  := false.B
        statusErrorNext := false.B
        descLoadIdx := 0.U
        dmaState    := dLoadDesc
      }
    }

    is(dLoadDesc) {
      // Issue a 4-byte read from descAddrReg + descLoadIdx*4
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.otherwise {
        val loadAddr = descAddrReg + (descLoadIdx << 2.U)
        io.tl_host.a.valid         := true.B
        io.tl_host.a.bits.opcode   := TLULOpcodesA.Get
        io.tl_host.a.bits.param    := 0.U
        io.tl_host.a.bits.size     := 2.U  // 4 bytes
        io.tl_host.a.bits.source   := 0.U
        io.tl_host.a.bits.address  := loadAddr
        io.tl_host.a.bits.mask     := 0xf.U
        io.tl_host.a.bits.data     := 0.U
        io.tl_host.a.bits.corrupt  := false.B

        when(io.tl_host.a.ready) {
          dmaState := dWaitDesc
        }
      }
    }

    is(dWaitDesc) {
      io.tl_host.d.ready := true.B
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.elsewhen(io.tl_host.d.valid) {
        // Extract the 4-byte word from the bus-width response.
        // TL-UL places read data at the byte lane corresponding to the address.
        val addr        = descAddrReg + (descLoadIdx << 2.U)
        val byteOffset  = addr(log2Ceil(hostTlp.dataBits / 8) - 1, 0)
        val bitOffset   = byteOffset << 3.U
        val word        = (io.tl_host.d.bits.data >> bitOffset)(31, 0)
        descWords(descLoadIdx) := word

        when(descLoadIdx === 7.U) {
          // All 8 words loaded — decode descriptor
          val flags = descWords(2)  // will be updated with word on this cycle
          // Use the freshly read word for index 7 but descriptor words 0-6 already latched
          // Decode once all 8 are done; we need to capture word 7 first
          // We'll decode in a separate cycle by going to dXferRead
          descSrcAddr   := descWords(0)
          descDstAddr   := descWords(1)
          // flags = word 2 (already latched)
          descNextDesc  := descWords(3)
          descPollAddr  := descWords(4)
          descPollMask  := descWords(5)
          descPollValue := descWords(6)
          // descWords(7) = reserved

          val fw = descWords(2)
          descXferLen   := fw(23, 0)
          descXferWidth := fw(26, 24)
          descSrcFixed  := fw(27)
          descDstFixed  := fw(28)
          descPollEn    := fw(29)

          xferSrcAddr   := descWords(0)
          xferDstAddr   := descWords(1)
          xferRemain    := fw(23, 0)
          // beat size = 1 << xfer_width
          xferBeatSize  := 1.U << fw(26, 24)

          dmaState := dXferRead
        }.otherwise {
          descLoadIdx := descLoadIdx + 1.U
          dmaState    := dLoadDesc
        }
      }
    }

    is(dXferRead) {
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.elsewhen(xferRemain === 0.U) {
        // Transfer complete for this descriptor
        when(descNextDesc =/= 0.U) {
          // Chain to next descriptor
          descAddrReg := descNextDesc
          descLoadIdx := 0.U
          dmaState    := dLoadDesc
        }.otherwise {
          statusBusyNext := false.B
          statusDoneNext := true.B
          dmaState       := dDone
        }
      }.otherwise {
        val beatSize = Mux(xferRemain >= xferBeatSize, xferBeatSize, xferRemain)
        val sizeLog2 = OHToUInt(beatSize)  // log2 of beat size

        io.tl_host.a.valid        := true.B
        io.tl_host.a.bits.opcode  := TLULOpcodesA.Get
        io.tl_host.a.bits.param   := 0.U
        io.tl_host.a.bits.size    := sizeLog2
        io.tl_host.a.bits.source  := 1.U
        io.tl_host.a.bits.address := xferSrcAddr
        io.tl_host.a.bits.mask    := ((1.U << beatSize) - 1.U) << xferSrcAddr(log2Ceil(hostTlp.dataBits / 8) - 1, 0)
        io.tl_host.a.bits.data    := 0.U
        io.tl_host.a.bits.corrupt := false.B

        when(io.tl_host.a.ready) {
          dmaState := dWaitRead
        }
      }
    }

    is(dWaitRead) {
      io.tl_host.d.ready := true.B
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.elsewhen(io.tl_host.d.valid) {
        readDataReg := io.tl_host.d.bits.data
        dmaState    := dXferWrite
      }
    }

    is(dXferWrite) {
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.otherwise {
        val beatSize = Mux(xferRemain >= xferBeatSize, xferBeatSize, xferRemain)
        val sizeLog2 = OHToUInt(beatSize)

        // Build byte mask: beatSize bytes at the destination byte offset
        val dstByteOff = xferDstAddr(log2Ceil(hostTlp.dataBits / 8) - 1, 0)
        val byteMask   = ((1.U << beatSize) - 1.U) << dstByteOff

        // Shift data from src byte offset to dst byte offset
        val srcByteOff = xferSrcAddr(log2Ceil(hostTlp.dataBits / 8) - 1, 0)
        val shiftedData = (readDataReg >> (srcByteOff << 3.U)) << (dstByteOff << 3.U)

        io.tl_host.a.valid        := true.B
        io.tl_host.a.bits.opcode  := TLULOpcodesA.PutFullData
        io.tl_host.a.bits.param   := 0.U
        io.tl_host.a.bits.size    := sizeLog2
        io.tl_host.a.bits.source  := 2.U
        io.tl_host.a.bits.address := xferDstAddr
        io.tl_host.a.bits.mask    := byteMask
        io.tl_host.a.bits.data    := shiftedData
        io.tl_host.a.bits.corrupt := false.B

        when(io.tl_host.a.ready) {
          dmaState := dWaitWrite
        }
      }
    }

    is(dWaitWrite) {
      io.tl_host.d.ready := true.B
      when(ctrlAbort) {
        statusBusyNext  := false.B
        statusErrorNext := true.B
        dmaState        := dError
      }.elsewhen(io.tl_host.d.valid) {
        // Advance pointers
        val beatSize = Mux(xferRemain >= xferBeatSize, xferBeatSize, xferRemain)
        when(!descSrcFixed) {
          xferSrcAddr := xferSrcAddr + beatSize
        }
        when(!descDstFixed) {
          xferDstAddr := xferDstAddr + beatSize
        }
        xferRemain := xferRemain - beatSize
        dmaState   := dXferRead
      }
    }

    is(dDone) {
      // Reset ctrl.start so a new transfer can be triggered later
      when(csrWriteEn && csrWriteAddr === 0x00.U) {
        // Allow software to write CTRL
      }.otherwise {
        // Keep done set until software clears it
      }
    }

    is(dError) {
      // Stay in error state until software clears
    }
  }

  // Update STATUS register
  statusReg := Cat(0.U(29.W), statusErrorNext, statusDoneNext, statusBusyNext)

  // When CTRL is written, handle abort
  when(csrWriteEn && csrWriteAddr === 0x00.U) {
    val newCtrl = csrWriteData
    when(newCtrl(2)) {
      // Abort requested
      statusBusyNext  := false.B
      statusErrorNext := true.B
      statusReg       := Cat(0.U(29.W), true.B, statusDoneNext, false.B)
      dmaState        := dError
    }
  }
}

