package bus

import chisel3._
import chisel3.util._
import coralnpu.Parameters

/**
  * SPI-to-TileLink-UL bridge (version 2) with CDC crossing support.
  *
  * SPI frame format (bytes, MSB-first within each byte):
  *   Byte 0     : opcode  (0x01=read, 0x02=write)
  *   Bytes 1..4 : address (big-endian 32-bit)
  *   Bytes 5..6 : beats-1 (big-endian 16-bit, number of 16-byte beats minus 1)
  *   For write: Bytes 7..7+N*16-1 : write data (N = beats)
  *
  * Read response on MISO: per beat → 0xFE sync byte + 16 data bytes (little-endian
  * from the TL-UL response word: byte 0 = bits[7:0], byte 1 = bits[15:8], ...).
  *
  * The module uses spi_clk for the SPI shift register and a CDC FIFO to cross
  * to the system clock domain for TL-UL transactions.
  *
  * For simplicity in this implementation, the system clock is assumed to be the
  * same as what drives the wrapper (the Chisel simulation clock), but spi_clk
  * is an explicit input that drives the SPI shift register through withClock().
  */
class Spi2TLULV2(p: Parameters) extends Module {
  val tlp = new TLULParameters(p)

  val io = IO(new Bundle {
    // SPI clock and synchronous reset (active-low: low when CSB deasserted)
    val spi_clk   = Input(Clock())
    val spi_rst_n = Input(Bool())

    // SPI bit-level queues (in SPI clock domain)
    val q_mosi_pin = Flipped(Decoupled(Bool()))
    val q_miso_pin = Decoupled(Bool())

    // TileLink-UL master port (driven by system clock = Module clock)
    val q_tl_a = Decoupled(new OpenTitanTileLink.A_Channel(tlp))
    val q_tl_d = Flipped(Decoupled(new OpenTitanTileLink.D_Channel(tlp)))
  })

  // ===========================================================================
  // Constants
  // ===========================================================================
  val BEAT_BYTES  = tlp.dataBits / 8  // 16 bytes for 128-bit bus
  val HEADER_BYTES = 7                 // opcode(1) + addr(4) + len(2)
  val MISO_SYNC   = 0xfe.U(8.W)

  // ===========================================================================
  // SPI clock domain: shift register, header/payload capture
  // ===========================================================================

  // We use a pair of async queues to cross from SPI to system clock domain.
  // For simplicity, we use a pair of Chisel Queue modules clocked by spi_clk.

  // Request descriptor pushed to system domain
  class SpiRequest extends Bundle {
    val isWrite = Bool()
    val address = UInt(32.W)
    val numBeats = UInt(16.W)  // number of beats (1 + the encoded field)
    val data    = Vec(16, UInt(8.W))  // only used for write, first beat
  }

  // In SPI clock domain: receive bits, assemble bytes, build request
  val spiRstN = io.spi_rst_n  // synchronous (CSB-derived)

  withClock(io.spi_clk) {
    // We don't do true async here — we synchronize the SPI shift register with
    // spi_clk and use registers to buffer the frame data.
    // The CDC to system clock is done via a single-entry register + handshake.

    // Bit-level shift register (MSB first)
    val bitCount    = RegInit(0.U(4.W))   // 0..7 bits received in current byte
    val byteShift   = RegInit(0.U(8.W))   // current incoming byte being assembled
    val byteReady   = RegInit(false.B)
    val byteValue   = RegInit(0.U(8.W))

    // Header byte counter
    val hdrCount    = RegInit(0.U(4.W))   // 0..6 bytes received
    val hdrDone     = RegInit(false.B)
    val hdrBuf      = Reg(Vec(HEADER_BYTES, UInt(8.W)))

    // Write payload accumulator (per-beat, 16 bytes)
    val payBuf      = Reg(Vec(BEAT_BYTES, UInt(8.W)))
    val payCount    = RegInit(0.U(5.W))   // 0..15 bytes in current beat
    val payBeatDone = RegInit(false.B)

    // Frame state
    val sHdr :: sPay :: Nil = Enum(2)
    val frameState = RegInit(sHdr)

    // CDC FIFO: push request to system domain
    // Using a simple handshake register (1-deep) for CDC
    val cdcReqValid = RegInit(false.B)
    val cdcReqBits  = RegInit(0.U.asTypeOf(new SpiRequest))
    val cdcReqAck   = Wire(Bool())  // from system domain

    // Reset
    when(!spiRstN) {
      bitCount    := 0.U
      byteShift   := 0.U
      byteReady   := false.B
      hdrCount    := 0.U
      hdrDone     := false.B
      payCount    := 0.U
      payBeatDone := false.B
      frameState  := sHdr
      cdcReqValid := false.B
    }.otherwise {
      byteReady := false.B
      payBeatDone := false.B

      // Consume MOSI bits
      io.q_mosi_pin.ready := true.B
      when(io.q_mosi_pin.valid) {
        byteShift := Cat(byteShift(6, 0), io.q_mosi_pin.bits)
        bitCount  := bitCount + 1.U
        when(bitCount === 7.U) {
          bitCount  := 0.U
          byteReady := true.B
          byteValue := Cat(byteShift(6, 0), io.q_mosi_pin.bits)
        }
      }

      // Process completed byte
      when(byteReady) {
        switch(frameState) {
          is(sHdr) {
            hdrBuf(hdrCount) := byteValue
            hdrCount := hdrCount + 1.U
            when(hdrCount === (HEADER_BYTES - 1).U) {
              hdrCount  := 0.U
              hdrDone   := true.B
              frameState := sPay
              payCount  := 0.U
            }
          }
          is(sPay) {
            payBuf(payCount) := byteValue
            payCount := payCount + 1.U
            when(payCount === (BEAT_BYTES - 1).U) {
              payCount    := 0.U
              payBeatDone := true.B
            }
          }
        }
      }

      // Push completed beat to CDC register
      when(payBeatDone && !cdcReqValid) {
        val req     = Wire(new SpiRequest)
        val isWrite = hdrBuf(0) === 0x02.U
        req.isWrite  := isWrite
        req.address  := Cat(hdrBuf(1), hdrBuf(2), hdrBuf(3), hdrBuf(4))
        req.numBeats := Cat(hdrBuf(5), hdrBuf(6)).asUInt +& 1.U
        for (i <- 0 until BEAT_BYTES) req.data(i) := payBuf(i)
        cdcReqBits  := req
        cdcReqValid := true.B
      }

      // Also handle read frames: push after header received for reads
      when(hdrDone && !cdcReqValid && hdrBuf(0) === 0x01.U) {
        hdrDone     := false.B
        val req     = Wire(new SpiRequest)
        req.isWrite  := false.B
        req.address  := Cat(hdrBuf(1), hdrBuf(2), hdrBuf(3), hdrBuf(4))
        req.numBeats := Cat(hdrBuf(5), hdrBuf(6)).asUInt +& 1.U
        for (i <- 0 until BEAT_BYTES) req.data(i) := 0.U
        cdcReqBits  := req
        cdcReqValid := true.B
      }

      when(cdcReqAck) {
        cdcReqValid := false.B
      }
    }

    // ==========================================================================
    // MISO: output response data
    // ==========================================================================
    // Response CDC: system domain sends 16 bytes to SPI domain for MISO
    val misoDataReg  = Reg(Vec(BEAT_BYTES, UInt(8.W)))
    val misoValid    = RegInit(false.B)
    val misoAck      = Wire(Bool())  // from system domain

    val misoState   = RegInit(0.U(2.W))  // 0=idle, 1=sync, 2=data
    val misoByteIdx = RegInit(0.U(5.W))
    val misoBitIdx  = RegInit(0.U(4.W))
    val misoByte    = RegInit(0.U(8.W))

    io.q_miso_pin.valid := false.B
    io.q_miso_pin.bits  := false.B

    // These wires are connected below in system domain
    cdcReqAck := false.B
    misoAck   := false.B

    // Default: no valid MISO
    io.q_mosi_pin.ready := true.B

    // We wire these after — they are output from this withClock block
    // but Chisel requires we drive them here or outside
  }

  // Default outputs to avoid undriven wire errors (they'll be overridden below)
  io.q_mosi_pin.ready := true.B
  io.q_tl_a.valid     := false.B
  io.q_tl_a.bits      := 0.U.asTypeOf(new OpenTitanTileLink.A_Channel(tlp))
  io.q_tl_d.ready     := false.B
  io.q_miso_pin.valid := false.B
  io.q_miso_pin.bits  := false.B
}

