import coralnpu.Parameters

/**
  * SPI-to-TileLink-UL bridge (version 2).
  *
  * SPI frame format (bytes, MSB-first within each byte):
  *   Byte 0     : opcode  (0x01=read, 0x02=write)
  *   Bytes 1..4 : address (big-endian 32-bit)
  *   Bytes 5..6 : beats-1 (big-endian 16-bit: 0 = 1 beat, 1 = 2 beats, etc.)
  *   For write: Bytes 7..7+N*16-1 : write data (N = beats, each beat 16 bytes)
  *
  * Read response on MISO per beat: 0xFE sync byte + 16 data bytes.
  * The 16 data bytes are the 128-bit TL-D response in little-endian byte order:
  *   byte 0 = data[7:0], byte 1 = data[15:8], ..., byte 15 = data[127:120].
  *
  * This module implements a two-clock design:
  *   - spi_clk domain: SPI shift register and byte assembly
  *   - system clock domain: TL-UL transactions
  *   - CDC via simple handshake registers (safe for low-rate SPI traffic)
  */
class Spi2TLULV2(p: Parameters) extends Module {
  val tlp = new TLULParameters(p)
  val BEAT_BYTES = tlp.dataBits / 8  // 16

  // SPI request descriptor (crosses from SPI → system domain)
  class SpiReqDesc extends Bundle {
    val isWrite  = Bool()
    val address  = UInt(32.W)
    val numBeats = UInt(16.W)   // total number of 16-byte beats
    val wdata    = UInt(tlp.dataBits.W)  // write data for this beat
  }

  val io = IO(new Bundle {
    val spi_clk   = Input(Clock())
    val spi_rst_n = Input(Bool())

    val q_mosi_pin = Flipped(Decoupled(Bool()))
    val q_miso_pin = Decoupled(Bool())

    val q_tl_a = Decoupled(new OpenTitanTileLink.A_Channel(tlp))
    val q_tl_d = Flipped(Decoupled(new OpenTitanTileLink.D_Channel(tlp)))
  })

  // ===========================================================================
  // CDC registers: SPI → System
  //   spiReqValid / spiReqAck handshake (toggle-based, but we use level here
  //   since SPI is much slower than sys clock)
  // ===========================================================================
  val spiToSysValid = Wire(Bool())
  val spiToSysReady = Wire(Bool())
  val spiToSysDesc  = Wire(new SpiReqDesc)

  // Sys → SPI: response data for MISO
  val sysToSpiValid = Wire(Bool())
  val sysToSpiReady = Wire(Bool())
  val sysToSpiData  = Wire(UInt(tlp.dataBits.W))

  // ===========================================================================
  // SPI clock domain
  // ===========================================================================

  // CDC FIFOs (async) — using Queue for simplicity with spi_clk
  // Since tests drive spi_clk via Bool and step sys clock, we use separate
  // clock domains via withClock.

  // SPI → Sys: request FIFO (depth 2 for safety)
  val spiToSysQueue = Module(new AsyncQueue(new SpiReqDesc, new AsyncQueueParams(depth = 4)))
  spiToSysQueue.io.enq_clock := io.spi_clk
  spiToSysQueue.io.enq_reset := (!io.spi_rst_n).asAsyncReset
  spiToSysQueue.io.deq_clock := clock
  spiToSysQueue.io.deq_reset := reset

  spiToSysValid := spiToSysQueue.io.deq.valid
  spiToSysDesc  := spiToSysQueue.io.deq.bits
  spiToSysQueue.io.deq.ready := spiToSysReady

  // Sys → SPI: response data FIFO
  val sysToSpiQueue = Module(new AsyncQueue(UInt(tlp.dataBits.W), new AsyncQueueParams(depth = 4)))
  sysToSpiQueue.io.enq_clock := clock
  sysToSpiQueue.io.enq_reset := reset
  sysToSpiQueue.io.deq_clock := io.spi_clk
  sysToSpiQueue.io.deq_reset := (!io.spi_rst_n).asAsyncReset

  sysToSpiValid := sysToSpiQueue.io.deq.valid
  sysToSpiQueue.io.deq.ready := sysToSpiReady

  sysToSpiData := sysToSpiQueue.io.deq.bits

  // Enqueue side is driven from system domain
  sysToSpiQueue.io.enq.valid := false.B
  sysToSpiQueue.io.enq.bits  := 0.U

  // ===========================================================================
  // SPI clock domain logic
  // ===========================================================================
  withClock(io.spi_clk) {
    val spiReset = (!io.spi_rst_n).asAsyncReset

    withReset(spiReset) {
      // Bit shift register
      val bitCnt   = RegInit(0.U(4.W))
      val bitBuf   = RegInit(0.U(8.W))  // current byte being assembled
      val byteRdy  = WireDefault(false.B)
      val byteVal  = Wire(UInt(8.W))
      byteVal := 0.U

      // Header parsing (7 bytes: opcode, addr[3:0], len[1:0])
      val hdrBuf  = Reg(Vec(7, UInt(8.W)))
      val hdrCnt  = RegInit(0.U(4.W))
      val hdrDone = RegInit(false.B)

      // Write payload: accumulate one beat (16 bytes) at a time
      val payBuf = Reg(Vec(BEAT_BYTES, UInt(8.W)))
      val payCnt = RegInit(0.U(5.W))

      // Beat counter
      val beatIdx     = RegInit(0.U(16.W))
      val numBeatsReg = RegInit(0.U(16.W))
      val isWriteReg  = RegInit(false.B)
      val addrReg     = RegInit(0.U(32.W))

      // Frame state machine
      val fsIdle :: fsHdr :: fsPay :: fsFlush :: Nil = Enum(4)
      val frameState = RegInit(fsIdle)

      // MISO state machine
      val msIdle :: msSync :: msData :: Nil = Enum(3)
      val misoState  = RegInit(msIdle)
      val misoByteIdx = RegInit(0.U(5.W))
      val misoBitIdx  = RegInit(0.U(4.W))
      val misoDataReg = RegInit(0.U(tlp.dataBits.W))
      val misoByteCur = RegInit(0.U(8.W))

      // Default IO
      io.q_mosi_pin.ready := true.B
      io.q_miso_pin.valid := false.B
      io.q_miso_pin.bits  := false.B
      spiToSysQueue.io.enq.valid := false.B
      spiToSysQueue.io.enq.bits  := 0.U.asTypeOf(new SpiReqDesc)
      sysToSpiReady := false.B

      // Consume MOSI bits
      when(io.q_mosi_pin.valid) {
        val newBuf = Cat(bitBuf(6, 0), io.q_mosi_pin.bits)
        bitBuf := newBuf
        bitCnt := bitCnt + 1.U
        when(bitCnt === 7.U) {
          bitCnt  := 0.U
          byteRdy := true.B
          byteVal := Cat(bitBuf(6, 0), io.q_mosi_pin.bits)
        }
      }

      // Process completed byte
      switch(frameState) {
        is(fsIdle) {
          when(byteRdy) {
            hdrBuf(0)  := byteVal
            hdrCnt     := 1.U
            frameState := fsHdr
          }
        }
        is(fsHdr) {
          when(byteRdy) {
            hdrBuf(hdrCnt) := byteVal
            hdrCnt := hdrCnt + 1.U
            when(hdrCnt === 6.U) {
              hdrCnt := 0.U
              // Decode header
              val op       = hdrBuf(0)
              val addr     = Cat(hdrBuf(1), hdrBuf(2), hdrBuf(3), hdrBuf(4))
              val lenField = Cat(hdrBuf(5), byteVal)
              val beats    = lenField +& 1.U
              isWriteReg  := op === 0x02.U
              addrReg     := addr
              numBeatsReg := beats
              beatIdx     := 0.U
              payCnt      := 0.U

              when(op === 0x01.U) {
                // Read: push request immediately for each beat
                frameState := fsFlush
              }.otherwise {
                // Write: collect payload
                frameState := fsPay
              }
            }
          }
        }
        is(fsPay) {
          when(byteRdy) {
            payBuf(payCnt) := byteVal
            payCnt := payCnt + 1.U
            when(payCnt === (BEAT_BYTES - 1).U) {
              payCnt := 0.U
              // Push this beat's request
              val req = Wire(new SpiReqDesc)
              req.isWrite  := true.B
              req.address  := addrReg + (beatIdx << log2Ceil(BEAT_BYTES).U)
              req.numBeats := numBeatsReg
              req.wdata    := Cat(payBuf.init.reverse.foldLeft(byteVal)((acc, b) => Cat(acc, b)).asUInt,
                                  0.U(0.W))
              // Little-endian packing: payBuf(0)=bits[7:0], payBuf(1)=bits[15:8], ...
              var dataWire = Wire(UInt(tlp.dataBits.W))
              dataWire := 0.U
              for (i <- 0 until BEAT_BYTES) {
                val byte_i = Mux(i.U < (BEAT_BYTES - 1).U, payBuf(i), byteVal)
                dataWire = (dataWire | (byte_i << (i * 8).U))(tlp.dataBits - 1, 0)
              }
              req.wdata := dataWire

              spiToSysQueue.io.enq.valid := true.B
              spiToSysQueue.io.enq.bits  := req

              beatIdx := beatIdx + 1.U
              when(beatIdx >= numBeatsReg - 1.U) {
                frameState := fsIdle
              }
            }
          }
        }
        is(fsFlush) {
          // For read: issue one request per beat immediately
          val req = Wire(new SpiReqDesc)
          req.isWrite  := false.B
          req.address  := addrReg + (beatIdx << log2Ceil(BEAT_BYTES).U)
          req.numBeats := numBeatsReg
          req.wdata    := 0.U

          when(spiToSysQueue.io.enq.ready) {
            spiToSysQueue.io.enq.valid := true.B
            spiToSysQueue.io.enq.bits  := req
            beatIdx := beatIdx + 1.U
            when(beatIdx >= numBeatsReg - 1.U) {
              frameState := fsIdle
            }
          }
        }
      }

      // MISO output: consume response data from sys domain
      switch(misoState) {
        is(msIdle) {
          when(sysToSpiValid) {
            sysToSpiReady := true.B
            misoDataReg   := sysToSpiData
            misoByteIdx   := 0.U
            misoBitIdx    := 7.U
            misoByteCur   := 0xfe.U  // sync byte first
            misoState     := msSync
          }
        }
        is(msSync) {
          // Emit 0xFE sync byte (8 bits, MSB first)
          io.q_miso_pin.valid := true.B
          io.q_miso_pin.bits  := misoByteCur(misoBitIdx)
          when(io.q_miso_pin.ready) {
            when(misoBitIdx === 0.U) {
              misoBitIdx  := 7.U
              misoByteIdx := 0.U
              // Move to data
              misoState   := msData
              // Grab first data byte
              misoByteCur := misoDataReg(7, 0)
            }.otherwise {
              misoBitIdx := misoBitIdx - 1.U
            }
          }
        }
        is(msData) {
          io.q_miso_pin.valid := true.B
          // Current byte in misoDataReg shifted by byte index
          val curByte = (misoDataReg >> (misoByteIdx << 3.U))(7, 0)
          io.q_miso_pin.bits := curByte(misoBitIdx)
          when(io.q_miso_pin.ready) {
            when(misoBitIdx === 0.U) {
              misoBitIdx := 7.U
              when(misoByteIdx === (BEAT_BYTES - 1).U) {
                // Beat done, go back to idle to wait for next response
                misoState := msIdle
              }.otherwise {
                misoByteIdx := misoByteIdx + 1.U
              }
            }.otherwise {
              misoBitIdx := misoBitIdx - 1.U
            }
          }
        }
      }
    }
  }

  // ===========================================================================
  // System clock domain: TL-UL transactions
  // ===========================================================================
  val sSysIdle :: sSysIssue :: sSysWaitD :: sSysResp :: Nil = Enum(4)
  val sysState = RegInit(sSysIdle)

  val pendAddr    = RegInit(0.U(32.W))
  val pendIsWrite = RegInit(false.B)
  val pendBeats   = RegInit(0.U(16.W))
  val pendBeatIdx = RegInit(0.U(16.W))
  val pendWdata   = RegInit(0.U(tlp.dataBits.W))
  val pendSource  = RegInit(0.U(tlp.sourceBits.W))

  spiToSysReady := false.B

  io.q_tl_a.valid := false.B
  io.q_tl_a.bits  := 0.U.asTypeOf(new OpenTitanTileLink.A_Channel(tlp))
  io.q_tl_d.ready := false.B
  sysToSpiQueue.io.enq.valid := false.B
  sysToSpiQueue.io.enq.bits  := 0.U

  switch(sysState) {
    is(sSysIdle) {
      when(spiToSysValid) {
        spiToSysReady := true.B
        pendAddr      := spiToSysDesc.address
        pendIsWrite   := spiToSysDesc.isWrite
        pendBeats     := spiToSysDesc.numBeats
        pendWdata     := spiToSysDesc.wdata
        pendBeatIdx   := 0.U
        pendSource    := 0.U
        sysState      := sSysIssue
      }
    }

    is(sSysIssue) {
      val beatAddr = pendAddr
      io.q_tl_a.valid          := true.B
      io.q_tl_a.bits.opcode    := Mux(pendIsWrite, TLULOpcodesA.PutFullData, TLULOpcodesA.Get)
      io.q_tl_a.bits.param     := 0.U
      io.q_tl_a.bits.size      := log2Ceil(BEAT_BYTES).U
      io.q_tl_a.bits.source    := pendSource
      io.q_tl_a.bits.address   := beatAddr
      io.q_tl_a.bits.mask      := ((BigInt(1) << BEAT_BYTES) - 1).U
      io.q_tl_a.bits.data      := pendWdata
      io.q_tl_a.bits.corrupt   := false.B
      io.q_tl_a.bits.user      := 0.U.asTypeOf(new OpenTitanTileLink_A_User)

      when(io.q_tl_a.ready) {
        sysState := sSysWaitD
      }
    }

    is(sSysWaitD) {
      io.q_tl_d.ready := true.B
      when(io.q_tl_d.valid) {
        when(!pendIsWrite) {
          // For reads: push response data to SPI domain
          sysToSpiQueue.io.enq.valid := true.B
          sysToSpiQueue.io.enq.bits  := io.q_tl_d.bits.data
        }
        sysState := sSysIdle
      }
    }
  }
}

