package bus

import chisel3._
import chisel3.util._
import coralnpu.Parameters
import freechips.rocketchip.util._

/**
  * SPI-to-TileLink-UL bridge (version 2).
  *
  * SPI frame format (bytes, MSB-first per byte):
  *   Byte 0     : opcode  (0x01=read, 0x02=write)
  *   Bytes 1..4 : address (big-endian 32-bit)
  *   Bytes 5..6 : beats-1 (big-endian 16-bit: 0=1 beat, N=N+1 beats)
  *   For write: Bytes 7..7+N*16-1 : N*16 write data bytes (one beat = 16 bytes)
  *
  * Read response on MISO per beat: 0xFE sync byte + 16 data bytes
  * (little-endian: byte[0]=data[7:0], ..., byte[15]=data[127:120]).
  */
class Spi2TLULV2(p: Parameters) extends Module {
  val tlp        = new TLULParameters(p)
  val BEAT_BYTES = tlp.dataBits / 8  // 16 bytes for 128-bit bus

  val io = IO(new Bundle {
    val spi_clk   = Input(Clock())
    val spi_rst_n = Input(Bool())     // low = reset (CSB deasserted state)

    val q_mosi_pin = Flipped(Decoupled(Bool()))
    val q_miso_pin = Decoupled(Bool())

    val q_tl_a = Decoupled(new OpenTitanTileLink.A_Channel(tlp))
    val q_tl_d = Flipped(Decoupled(new OpenTitanTileLink.D_Channel(tlp)))
  })

  // ===========================================================================
  // SPI request descriptor (SPI domain → System domain)
  // ===========================================================================
  class SpiReqDesc extends Bundle {
    val isWrite = Bool()
    val address = UInt(32.W)
    val wdata   = UInt(tlp.dataBits.W)
  }

  val spiReset = !io.spi_rst_n  // true when in reset

  // ===========================================================================
  // Async queues
  // ===========================================================================
  val spiToSys = Module(new AsyncQueue(new SpiReqDesc, AsyncQueueParams(depth = 4, safe = false)))
  spiToSys.io.enq_clock := io.spi_clk
  spiToSys.io.enq_reset := spiReset
  spiToSys.io.deq_clock := clock
  spiToSys.io.deq_reset := reset.asBool

  val sysToSpi = Module(new AsyncQueue(UInt(tlp.dataBits.W), AsyncQueueParams(depth = 4, safe = false)))
  sysToSpi.io.enq_clock := clock
  sysToSpi.io.enq_reset := reset.asBool
  sysToSpi.io.deq_clock := io.spi_clk
  sysToSpi.io.deq_reset := spiReset

  // ===========================================================================
  // SPI clock domain — all registers clocked by spi_clk, reset by spiReset
  // ===========================================================================

  // --- Bit accumulator ---
  val bitCnt = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(4.W)) }
  val bitBuf = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(8.W)) }

  // byteRdy / byteVal are combinational signals produced from the current bit
  val byteRdy = Wire(Bool())
  val byteVal = Wire(UInt(8.W))
  byteRdy := false.B
  byteVal := 0.U

  io.q_mosi_pin.ready := true.B
  withClock(io.spi_clk) {
    withReset(spiReset) {
      when(io.q_mosi_pin.valid) {
        val newBuf = Cat(bitBuf(6, 0), io.q_mosi_pin.bits.asUInt)
        bitBuf := newBuf
        bitCnt := bitCnt + 1.U
        when(bitCnt === 7.U) {
          bitCnt  := 0.U
          byteRdy := true.B
          byteVal := Cat(bitBuf(6, 0), io.q_mosi_pin.bits.asUInt)
        }
      }
    }
  }

  // --- Header / payload state machine (SPI clock domain) ---
  val hdrBuf  = withClockAndReset(io.spi_clk, spiReset) { Reg(Vec(7, UInt(8.W))) }
  val hdrCnt  = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(4.W)) }
  val inHdr   = withClockAndReset(io.spi_clk, spiReset) { RegInit(true.B) }

  val payBuf  = withClockAndReset(io.spi_clk, spiReset) { Reg(Vec(BEAT_BYTES, UInt(8.W))) }
  val payCnt  = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(5.W)) }

  val isWriteReg  = withClockAndReset(io.spi_clk, spiReset) { RegInit(false.B) }
  val addrReg     = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(32.W)) }
  val numBeatsReg = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(16.W)) }
  val beatIdx     = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(16.W)) }

  val rdPending = withClockAndReset(io.spi_clk, spiReset) { RegInit(false.B) }
  val rdBeatIdx = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(16.W)) }

  spiToSys.io.enq.valid := false.B
  spiToSys.io.enq.bits  := 0.U.asTypeOf(new SpiReqDesc)

  withClock(io.spi_clk) {
    withReset(spiReset) {
      // Byte processing
      when(byteRdy) {
        when(inHdr) {
          hdrBuf(hdrCnt) := byteVal
          hdrCnt := hdrCnt + 1.U
          when(hdrCnt === 6.U) {
            hdrCnt := 0.U
            val op    = hdrBuf(0)
            val addr  = Cat(hdrBuf(1), hdrBuf(2), hdrBuf(3), hdrBuf(4))
            val lf    = Cat(hdrBuf(5), byteVal)
            isWriteReg  := op === 0x02.U
            addrReg     := addr
            numBeatsReg := lf +& 1.U
            beatIdx     := 0.U
            payCnt      := 0.U
            when(op === 0x02.U) {
              inHdr := false.B
            }.otherwise {
              // Read: trigger immediate dispatch
              rdPending := true.B
              rdBeatIdx := 0.U
            }
          }
        }.otherwise {
          // Write payload
          payBuf(payCnt) := byteVal
          payCnt := payCnt + 1.U
          when(payCnt === (BEAT_BYTES - 1).U) {
            payCnt := 0.U
            // Pack bytes LE: byte 0 = bits[7:0], ..., byte 15 = bits[127:120]
            val wdata = Cat(
              byteVal,
              payBuf(14), payBuf(13), payBuf(12), payBuf(11),
              payBuf(10), payBuf(9),  payBuf(8),  payBuf(7),
              payBuf(6),  payBuf(5),  payBuf(4),  payBuf(3),
              payBuf(2),  payBuf(1),  payBuf(0)
            )
            val req = Wire(new SpiReqDesc)
            req.isWrite := true.B
            req.address := addrReg + (beatIdx << log2Ceil(BEAT_BYTES).U)
            req.wdata   := wdata
            spiToSys.io.enq.valid := true.B
            spiToSys.io.enq.bits  := req

            beatIdx := beatIdx + 1.U
            when(beatIdx >= numBeatsReg - 1.U) {
              inHdr := true.B
            }
          }
        }
      }

      // Dispatch read requests
      when(rdPending && !byteRdy) {
        val req = Wire(new SpiReqDesc)
        req.isWrite := false.B
        req.address := addrReg + (rdBeatIdx << log2Ceil(BEAT_BYTES).U)
        req.wdata   := 0.U
        when(spiToSys.io.enq.ready && !spiToSys.io.enq.valid) {
          spiToSys.io.enq.valid := true.B
          spiToSys.io.enq.bits  := req
          rdBeatIdx := rdBeatIdx + 1.U
          when(rdBeatIdx >= numBeatsReg - 1.U) {
            rdPending := false.B
          }
        }
      }
    }
  }

  // --- MISO output (SPI clock domain) ---
  val msIdle :: msSync :: msData :: Nil = Enum(3)
  val misoState  = withClockAndReset(io.spi_clk, spiReset) { RegInit(msIdle) }
  val misoData   = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(tlp.dataBits.W)) }
  val misoByteCnt = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(5.W)) }
  val misoBitCnt  = withClockAndReset(io.spi_clk, spiReset) { RegInit(0.U(4.W)) }

  io.q_miso_pin.valid := false.B
  io.q_miso_pin.bits  := false.B
  sysToSpi.io.deq.ready := false.B

  withClock(io.spi_clk) {
    withReset(spiReset) {
      switch(misoState) {
        is(msIdle) {
          sysToSpi.io.deq.ready := true.B
          when(sysToSpi.io.deq.valid) {
            misoData    := sysToSpi.io.deq.bits
            misoBitCnt  := 7.U
            misoByteCnt := 0.U
            misoState   := msSync
          }
        }
        is(msSync) {
          // Emit 0xFE sync byte MSB first
          io.q_miso_pin.valid := true.B
          io.q_miso_pin.bits  := 0xfe.U(8.W)(misoBitCnt)
          when(io.q_miso_pin.ready) {
            when(misoBitCnt === 0.U) {
              misoBitCnt  := 7.U
              misoByteCnt := 0.U
              misoState   := msData
            }.otherwise {
              misoBitCnt := misoBitCnt - 1.U
            }
          }
        }
        is(msData) {
          // Emit data bytes, little-endian, MSB first per byte
          val curByte = (misoData >> (misoByteCnt << 3.U))(7, 0)
          io.q_miso_pin.valid := true.B
          io.q_miso_pin.bits  := curByte(misoBitCnt)
          when(io.q_miso_pin.ready) {
            when(misoBitCnt === 0.U) {
              misoBitCnt := 7.U
              when(misoByteCnt === (BEAT_BYTES - 1).U) {
                misoByteCnt := 0.U
                misoState   := msIdle
              }.otherwise {
                misoByteCnt := misoByteCnt + 1.U
              }
            }.otherwise {
              misoBitCnt := misoBitCnt - 1.U
            }
          }
        }
      }
    }
  }

  // ===========================================================================
  // System clock domain: TL-UL transactions
  // ===========================================================================
  val sIdle :: sIssue :: sWaitD :: Nil = Enum(3)
  val sysState = RegInit(sIdle)

  val pendAddr    = RegInit(0.U(32.W))
  val pendIsWrite = RegInit(false.B)
  val pendWdata   = RegInit(0.U(tlp.dataBits.W))

  io.q_tl_a.valid     := false.B
  io.q_tl_a.bits      := 0.U.asTypeOf(new OpenTitanTileLink.A_Channel(tlp))
  io.q_tl_d.ready     := false.B
  spiToSys.io.deq.ready := false.B
  sysToSpi.io.enq.valid := false.B
  sysToSpi.io.enq.bits  := 0.U

  switch(sysState) {
    is(sIdle) {
      spiToSys.io.deq.ready := true.B
      when(spiToSys.io.deq.valid) {
        pendAddr    := spiToSys.io.deq.bits.address
        pendIsWrite := spiToSys.io.deq.bits.isWrite
        pendWdata   := spiToSys.io.deq.bits.wdata
        sysState    := sIssue
      }
    }

    is(sIssue) {
      io.q_tl_a.valid          := true.B
      io.q_tl_a.bits.opcode    := Mux(pendIsWrite, TLULOpcodesA.PutFullData, TLULOpcodesA.Get)
      io.q_tl_a.bits.param     := 0.U
      io.q_tl_a.bits.size      := log2Ceil(BEAT_BYTES).U
      io.q_tl_a.bits.source    := 0.U
      io.q_tl_a.bits.address   := pendAddr
      io.q_tl_a.bits.mask      := ((BigInt(1) << BEAT_BYTES) - 1).U
      io.q_tl_a.bits.data      := pendWdata
      io.q_tl_a.bits.corrupt   := false.B
      io.q_tl_a.bits.user      := 0.U.asTypeOf(new OpenTitanTileLink_A_User)

      when(io.q_tl_a.ready) {
        sysState := sWaitD
      }
    }

    is(sWaitD) {
      io.q_tl_d.ready := true.B
      when(io.q_tl_d.valid) {
        when(!pendIsWrite) {
          sysToSpi.io.enq.valid := true.B
          sysToSpi.io.enq.bits  := io.q_tl_d.bits.data
        }
        sysState := sIdle
      }
    }
  }
