val hdrCnt   = RegInit(0.U(3.W))  // 3-bit: 0..6
val inHdr    = RegInit(true.B)
val frameDone = RegInit(false.B)  // stop processing bytes after frame is complete

// Payload
val payBuf  = Reg(Vec(BEAT_BYTES, UInt(8.W)))
val payCnt  = RegInit(0.U(4.W))  // 4-bit: 0..15 for BEAT_BYTES=16

val isWriteReg  = RegInit(false.B)
