is(spiBit) {
  halfCnt := halfCnt + 1.U
  when(halfCnt >= spiHalfPeriod - 1.U) {
    halfCnt := 0.U

    // Toggle SCLK
    val nextSclk = !sclkReg
    sclkReg := nextSclk

    // Determine if this is a leading or trailing edge
    // Leading edge: CPOL=0 → rising (sclkReg=0→1), CPOL=1 → falling (sclkReg=1→0)
    // sclkReg is the OLD value (before toggle)
    val isLeadingEdge = Mux(cpol, sclkReg, !sclkReg)

    // CPHA=0: sample on leading, shift on trailing
    // CPHA=1: sample on trailing (second), shift on leading (first)
    val sampleOnThisEdge = Mux(cpha, !isLeadingEdge, isLeadingEdge)

    when(sampleOnThisEdge) {
      // Sample MISO, shift into rxShift MSB first
      rxShift := Cat(rxShift(6, 0), io.spi.miso)
      // After sampling all 8 bits
      when(bitCnt === 7.U) {
        spiState := spiDone
      }.otherwise {
        bitCnt := bitCnt + 1.U
      }
    }.otherwise {
      // Shift MOSI: output next bit
      // CPHA=0: shift on trailing edge; bitCnt was just incremented by the preceding sample.
      //   bitCnt=1..7 → output bits 6..0 = shiftReg(7-bitCnt)
      //   We also need bitCnt=7 to output bit 0 for the last (8th) sample edge.
      // CPHA=1: shift on leading edge; bitCnt not yet incremented.
      //   bitCnt=0..6 → output bits 6..0 = shiftReg(6-bitCnt)
      //   Guard bitCnt<7 to avoid underflow on the 8th leading edge.
      when(!cpha) {
        mosiReg := shiftReg(7.U - bitCnt)
      }.elsewhen(bitCnt < 7.U) {
        mosiReg := shiftReg(6.U - bitCnt)
      }
    }
  }
}

input.new_string:
is(spiBit) {
  halfCnt := halfCnt + 1.U
  when(halfCnt >= spiHalfPeriod - 1.U) {
    halfCnt := 0.U

    // Toggle SCLK. sclkReg is the OLD value (before toggle).
    sclkReg := !sclkReg

    // Leading edge: CPOL=0 → rising (sclkReg was 0), CPOL=1 → falling (sclkReg was 1)
    val isLeadingEdge  = Mux(cpol, sclkReg, !sclkReg)
    val isTrailingEdge = !isLeadingEdge

    when(!cpha) {
      // CPHA=0: sample on leading edge, shift MOSI on trailing edge.
      // The simple loopback (miso = mosi before each step) works because:
      //   leading: sample miso = current mosiReg (unchanged since last trailing shift).
      //   trailing: change mosiReg → reflects on miso before NEXT leading.
      when(isLeadingEdge) {
        rxShift := Cat(rxShift(6, 0), io.spi.miso)
        when(bitCnt === 7.U) {
          spiState := spiDone
        }.otherwise {
          bitCnt := bitCnt + 1.U
        }
      }.otherwise {
        // Trailing edge: update MOSI for the next sample.
        // bitCnt has already been incremented at the preceding leading edge.
        mosiReg := shiftReg(7.U - bitCnt)
      }
    }.otherwise {
      // CPHA=1: do nothing on leading edge; sample AND shift on trailing edge.
      // The simple loopback works because mosiReg is unchanged on the leading edge,
      // so when we poke miso=mosi before the trailing step, miso still has the
      // current-bit value (set at the previous trailing edge or from loadNextByte).
      when(isTrailingEdge) {
        rxShift := Cat(rxShift(6, 0), io.spi.miso)
        // Shift MOSI to next bit simultaneously (register reads are old values).
        when(bitCnt < 7.U) {
          mosiReg := shiftReg(6.U - bitCnt)
        }
        when(bitCnt === 7.U) {
          spiState := spiDone
        }.otherwise {
          bitCnt := bitCnt + 1.U
        }
      }
      // Leading edge: do nothing (no sample, no MOSI change).
    }
  }
}

