is(msData) {
  val curByte = (misoData >> (misoByteCnt << 3.U))(7, 0)
  io.miso_valid := true.B
  io.miso_bits  := curByte(misoBitCnt)
  when(io.miso_ready) {
    when(misoBitCnt === 0.U) {
      misoBitCnt := 7.U
      when(misoByteCnt === (BEAT_BYTES - 1).U) {
        misoByteCnt := 0.U
        // If next beat is already available, dequeue it now and go straight
        // to msSync — avoids a 1-cycle msIdle gap that would shift sync-byte
        // timing and confuse the receiver.
        io.deq_ready := true.B
        when(io.deq_valid) {
          misoData  := io.deq_bits
          misoState := msSync
        }.otherwise {
          misoState := msIdle
        }
      }.otherwise {
        misoByteCnt := misoByteCnt + 1.U
      }
    }.otherwise {
      misoBitCnt := misoBitCnt - 1.U
    }
  }
}
